"""Saved mission workspace; effects and model requests stay in explicit CLI flows."""
MISSION_STYLE=r'''
.missionflow{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:20px 0}.missionstage{border:1px solid var(--line);padding:17px;border-radius:14px}.missionstage.done{border-color:var(--accent)}.missionstage .label{margin-bottom:8px}.missionstage strong{display:block;font-size:18px}.missionwindows{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}.missionwindow{padding:8px 12px;border-radius:8px;border:1px solid var(--line);font-variant-numeric:tabular-nums}.missionwindow.bad{border-color:#bb724f;background:rgba(187,114,79,.08)}.missionledger{max-height:450px;overflow:auto}.missioncommands code{display:block;white-space:pre-wrap;overflow-wrap:anywhere;padding:12px;background:var(--bg);border-radius:9px;margin-top:10px}@media(max-width:760px){.missionflow{grid-template-columns:1fr}}
'''
MISSION_SCRIPT=r'''
let missionTimer=null,missionData=null,missionHandledJob=null;
function missionPaint(d){
 const s=d.summary;missionData=d;const child=s.service,firstRecovery=s.events.find(e=>e.kind==="BOUNDED_RECOVERY_RECORDED")?.data?.result,plan=child?.plans?.at(-1);
 const roleCard=(role,title,label)=>{const call=s.calls.find(c=>c.role===role),decision=s.decisions[role];return `<article class="missionstage ${call?.status==="VALIDATED"?"done":""}"><div class="label">${label}</div><strong>${title}</strong><p>${esc(call?human(call.status):"Not requested")}</p>${decision?`<p class="small">${esc(decision.reason)}</p>`:""}${call?evidence("Role handoff and response",call):""}</article>`;};
 const next={AWAITING_BATCH_APPROVAL:"approve",INCIDENT_RECORDED:"advance",AWAITING_RECOVERY_APPROVAL:"recover",MONITORING:"watch",OWNER_APPLYING:"advance",EXECUTING_BATCH:"advance",RECOVERING:"advance"}[s.phase];
 const windows=s.health.map(r=>{const passed=Object.values(r.samples).flat().filter(x=>x.ok===true&&x.body?.result===49).length;return `<div class="missionwindow ${r.bad?"bad":""}"><strong>Window ${r.sequence}</strong><br>${passed}/40 HTTP successes · ${r.bad?"incident signal":"healthy"}${r.workflow_paused?" · A paused":""}</div>`;}).join("");
 $("#missionbody").innerHTML=`<div class="pillrow">${badge(human(s.phase),s.phase==="RECOVERED_SERVICE_ACTIVE"?"good":"info")}${badge(s.mode,"info")}${badge(s.lifecycle==="STOPPED"?"Demo workers stopped":s.lease_elapsed?"Lease elapsed":"Saved leased-service observation","info")}</div>${s.historical_source?'<div class="callout warning">Historical source. Use the saved version to recompute this mission before continuing it.</div>':""}<div class="grid g4">${metric("Role proposals",`${s.role_requests} / 3`,"Distinct Factory, Governance and Recovery prompts")}${metric("Approved batch",plan?`${plan.choice.accepted.length} / ${plan.basis.intents.length}`:"Pending","Exact plan approval precedes requested effects")}${metric("Health windows",s.health.length,"Two consecutive bad windows create one incident")}${metric("Paid attempts",s.model_calls,`${s.usage.reported_tokens} reported tokens · ${s.usage.missing_usage_calls} without usage`)}</div><div class="missionflow">${roleCard("factory","Factory","Part 6 · create the challenge")}${roleCard("governance","Governance","Part 9 · order the requests")}${roleCard("recovery","Recovery","Part 12 · propose bounded cleanup")}</div><div class="grid g2"><article class="card"><h2>One continuing service</h2><p>${esc(s.goal)}</p>${child?`<p class="small">Runtime ${esc(child.runtime_id)}. The request queue, approvals, execution, incident and owner decisions share this service.</p><table><thead><tr><th>Boundary</th><th>Committed units</th><th>Result</th></tr></thead><tbody><tr><td>Initial service</td><td>60 / 100</td><td>Stable 40 + candidate 20</td></tr><tr><td>Reviewed batch</td><td>${plan?.choice.committed_units??"—"} / ${plan?.choice.capacity_limit??"—"}</td><td>${esc(human(s.batch_result?.status??"Awaiting consent"))}</td></tr><tr><td>First recovery</td><td>${firstRecovery?.committed_units??"—"} / ${firstRecovery?.capacity_limit??"—"}</td><td>${esc(human(firstRecovery?.status??"Not requested"))}</td></tr><tr><td>Saved final state</td><td>${child.metrics.committed} / ${child.metrics.limit}</td><td>${child.actual_at_outcome.candidate_percent}% candidate traffic</td></tr></tbody></table>`:'<p>The Factory reply is validated and independently rehearsed before starting workers.</p>'}<p class="small">Capacity and caller identity are local fixtures. Workers serve arithmetic over real HTTP.</p></article><article class="card"><h2>Recovery preserves another owner</h2>${firstRecovery?`<p>${esc(human(firstRecovery.status))}. Candidate traffic at the first recovery boundary: ${firstRecovery.final_routing?.["candidate-v2"]??"Unknown"}%.</p><p>Later C decisions: ${esc(s.owner_requests.map(r=>human(r.decision)).join(" → ")||"None recorded; C work remains retained")}.</p><p class="small">A remains ${child?.policy_snapshot.state.paused_runs.includes("deploy-A")?"paused":"active"}. A Recovery recommendation cannot authorize C withdrawal or resume A.</p>${evidence("Incident-bound manager grant",s.recovery_grant)}${evidence("Separate C owner decisions",s.owner_requests)}`:'<p>A Recovery request is made only after a measured incident. Exact manager consent precedes its effects; C reviews its own work separately.</p>'}</article></div><article class="card"><h2>Measured health and incident detection</h2><p class="small">Each window uses 20 routed, 10 stable and 10 candidate requests. An A workflow pause also signals failure. Healthy observations reset the counter. Supervisor connection loss is recorded separately.</p><div class="missionwindows">${windows||'<p>No windows recorded yet.</p>'}</div>${s.incident?evidence("The exact measured incident",s.incident):'<p>No confirmed incident has been recorded.</p>'}<p class="small">${esc(s.liveness_scope)} A terminal watch runs for a bounded duration; this saved view does not monitor in the background.</p></article><article class="card missioncommands"><h2>${s.lifecycle==="STOPPED"?"Try a persistent mission":"Continue in PowerShell"}</h2>${s.lifecycle==="STOPPED"?'<p>The finite demo completed its separate teardown. Start a fresh mission to review each boundary yourself.</p><code>.\\.venv\\Scripts\\python.exe project.py mission start</code>':`<p>Current phase: ${esc(human(s.phase))}. Use the printed exact review phrase when prompted.</p><code>.\\.venv\\Scripts\\python.exe project.py mission ${esc(next||"status")} --mission ${esc(s.mission_id)}${s.live&&next==="advance"?" --live --max-output-tokens 8192":""}</code>${s.phase==="AWAITING_OWNER_REVIEW"?`<code>.\\.venv\\Scripts\\python.exe project.py mission owner --mission ${esc(s.mission_id)} --decision retain</code>`:""}`}<p class="small">The free demo uses scripted proposals and consent fixtures. A real Nemotron mission uses explicit --live in the terminal, at most one attempt per role. Credentials are entered locally, hidden.</p></article><details><summary>Inspect the mission event ledger and execution evidence</summary><div class="card missionledger">${evidence("All mission transitions",s.events)}${evidence("Batch and recovery consent",{batch:s.batch_consent,recovery:s.recovery_grant})}${child?evidence("Exact service actions and receipts",child.coordination_events):""}${evidence("Usage and unknown outcomes",s.usage)}${child?'<button id="missionreplay">Inspect the policy replay</button><div id="missionreplaybody"></div>':""}</div></details>`;
}
async function missionView(ticket){
 choose("mission");missionData=null;
 const busy=["RUNNING","QUEUED"].includes(catalog.lab?.job?.status),options=(catalog.runs.mission||[]).map(r=>`<option value="${esc(r.id)}" ${selected.mission===r.id?"selected":""}>${esc(stamp(r.id))} · ${esc(human(r.summary.status))}</option>`).join("");
 $("#content").innerHTML=title("Mission control","Three agents. One supervised workflow.","Generate competing requests, review an exact batch, observe the same service and recover only what the approvals allow.","Parts 6 · 9 · 12")+`<div class="sessioncontrols"><label>Saved mission<select id="missionrun">${options||'<option value="">No missions yet</option>'}</select></label><button id="startmission" ${catalog.lab?.enabled&&catalog.lab?.available?.mission&&!busy?"":"disabled"}>Run free complete mission</button></div><p class="small">The fixed free example includes an explicit workflow fault, two measured failed windows, separate scripted approvals and final worker teardown. Live proposals and persistent exact reviews use PowerShell.</p>${coordinationJob()}<div id="missionbody"><div class="empty"><h2>Connect the full agent loop</h2><p>Factory → Governance → exact batch → monitoring → Recovery → C owner review. The same leased workers and durable receipts remain attached.</p></div></div>`;
 if(selected.mission){const d=await api(`/api/run?kind=mission&id=${encodeURIComponent(selected.mission)}`);if(ticket!==generation||tab!=="mission")return;missionPaint(d);}
 if(ticket===generation&&tab==="mission"&&busy)missionTimer=setTimeout(()=>pollMission(ticket),2000);
}
async function pollMission(ticket){if(ticket!==generation||tab!=="mission")return;try{const next=await api("/api/catalog");if(ticket!==generation||tab!=="mission")return;catalog=next;const j=catalog.lab?.job;if(j?.kind==="mission"&&j.status==="COMPLETED"&&missionHandledJob!==j.id){missionHandledJob=j.id;selected.mission=j.result.run;}await render();}catch(err){notice(err.message);}}
document.addEventListener("click",async e=>{const b=e.target.closest("button");if(!b)return;if(b.id==="startmission"&&tab==="mission"&&!b.disabled){b.disabled=true;try{const d=await api("/api/jobs",{method:"POST",headers:{"Content-Type":"application/json","X-Rehearsal-Token":LAB_TOKEN},body:JSON.stringify({kind:"mission"})});catalog.lab.job=d.job;await render();}catch(err){notice(err.message);b.disabled=false;}}else if(b.id==="missionreplay"&&missionData)renderReplay(missionData,"#missionreplaybody");});
document.addEventListener("change",async e=>{if(e.target.id==="missionrun"){selected.mission=e.target.value;await render();}});
'''
